-- composition of rule kernels L:eliminate_cross_join x L:eliminate_outer_join (datafusion), template product
SELECT count(*) FROM (WITH cte1 AS (SELECT ARRAY['1'::text] AS c0, '2000-01-01 00:00:00+00'::timestamptz AS c1, a1.c0 AS c2 FROM tp AS a1, generate_series (10, 5) AS a2 (c0) WHERE (a2.c0 > a1.c0) GROUP BY ROLLUP (a1.c0)) SELECT '_'::text AS c0, 1000::bigint AS c1, 100::bigint AS c2 INTERSECT SELECT '[1,10)'::text AS c0, 0::bigint AS c1, (NULL::bigint + 10::bigint) AS c2 FROM cte1 AS a3 GROUP BY a3.c2) AS ka CROSS JOIN (WITH cte1 AS (SELECT DISTINCT ROUND ((42.5::numeric - NULL::numeric), 2) AS c0, a1.n AS c1, '_'::text AS c2 FROM (v0 AS a1 FULL JOIN t1 AS a2 ON (a1.c0 = a2.c0)) WHERE (FALSE <= (a2.c0 BETWEEN 2 AND 3))) SELECT a3.c0 AS c0, 'a'::text AS c1, (CASE WHEN FALSE THEN '7 days'::interval ELSE GREATEST ('7 days'::interval, (SELECT MIN ('1 day'::interval) FROM cte1 AS a4 WHERE TRUE)) END + '1 year 2 months 3 days 4 hours 5 minutes 6.789 seconds'::interval) AS c2 FROM generate_series (5, 10) AS a3 (c0)) AS kb;
-- pgfuzz:check kernel:product SELECT (SELECT count(*) FROM (WITH cte1 AS (SELECT ARRAY['1'::text] AS c0, '2000-01-01 00:00:00+00'::timestamptz AS c1, a1.c0 AS c2 FROM tp AS a1, generate_series (10, 5) AS a2 (c0) WHERE (a2.c0 > a1.c0) GROUP BY ROLLUP (a1.c0)) SELECT '_'::text AS c0, 1000::bigint AS c1, 100::bigint AS c2 INTERSECT SELECT '[1,10)'::text AS c0, 0::bigint AS c1, (NULL::bigint + 10::bigint) AS c2 FROM cte1 AS a3 GROUP BY a3.c2) AS ka) * (SELECT count(*) FROM (WITH cte1 AS (SELECT DISTINCT ROUND ((42.5::numeric - NULL::numeric), 2) AS c0, a1.n AS c1, '_'::text AS c2 FROM (v0 AS a1 FULL JOIN t1 AS a2 ON (a1.c0 = a2.c0)) WHERE (FALSE <= (a2.c0 BETWEEN 2 AND 3))) SELECT a3.c0 AS c0, 'a'::text AS c1, (CASE WHEN FALSE THEN '7 days'::interval ELSE GREATEST ('7 days'::interval, (SELECT MIN ('1 day'::interval) FROM cte1 AS a4 WHERE TRUE)) END + '1 year 2 months 3 days 4 hours 5 minutes 6.789 seconds'::interval) AS c2 FROM generate_series (5, 10) AS a3 (c0)) AS kb)
